WITH amiodarone_prescriptions AS (SELECT (stoptime - starttime) AS duration FROM prescriptions WHERE drug = 'Amiodarone' AND subject_id = 123456789 AND hadm_id IN (SELECT hadm_id FROM admissions WHERE subject_id = 123456789 AND gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, DOB)) BETWEEN 62 AND 72)) SELECT (percentile_cont(0.75) within GROUP (ORDER BY duration) - percentile_cont(0.25) within GROUP (ORDER BY duration)) AS interquartile_range FROM amiodarone_prescriptions;